import logo from './logo.svg';
import './App.css';
import React, { useState, useEffect } from 'react';
import MainPage from './components/MainPage';
import { BrowserRouter, Route, Routes } from 'react-router-dom';
import { booleanContext, usernameContext, oppositeContext, incrementContext, refreshContext, usersContext, proccessContext } from './Context';
import Forgot from './components/Forgot';
import NewPassword from './components/NewPassword'
import Logout from './components/Logout';
import { StompSessionProvider } from 'react-stomp-hooks';
import axios from './api/axios';



function App() {
  const [isLoggedIn, setIsLoggedIn]=useState(false);
  const refreshToken = localStorage.getItem("Refresh Token Copy");
  const accessToken = localStorage.getItem("Access Token")
  const connectHeaders={
headers :{
        'Content-Type' : 'application/json',
        AUTHORIZATION : 'Bearer ' +localStorage.getItem("Refresh Token Copy")

            }}
console.log(refreshToken);

let csrf = ""
const getCsrf = async (e) =>{
csrf = axios.get("/csrf")
}
getCsrf()
console.log(csrf);


  return(
<>
<StompSessionProvider



    url={'http://localhost:8080/ws'}

            debug={STOMP => console.log({STOMP}

            )}

      connectHeaders={connectHeaders}


            onConnect={() => console.log({STOMP_CONNECT: 'TCP connection successfully established'})}

       >
<booleanContext.Provider value={{isLoggedIn, setIsLoggedIn}}>

<Routes>
<Route index element={<MainPage />} />
<Route>
<Route path="/forgot" element={<Forgot />} />
<Route path="/logout" element={<Logout />} />

<Route path="/changePassword"element={<NewPassword />} />
          <Route path="/" element={<MainPage />} />
        </Route>

</Routes>
</booleanContext.Provider>
</StompSessionProvider>
</>
  );
}

export default App;
